                    return list(payload[k])
            return []
        return v
    if kind in ("threshold", "prefix"):
        v = _get_list(payload, "vals", "Vals", "values", "Values")
        return v if v is not None else []
    # generic: items dict or vals list
    if isinstance(payload, dict) and "items" in payload:
        items = payload["items"]
        return list(items) if md == "a" else list(items.values())
    v = _get_list(payload, "vals", "Vals")
    return v if v is not None else []


